#include "matrix_pro/matrix_pro.hpp"
#include <iostream>

int main() {
    using matrix_pro::Matrix;

    // 1) Host'ta kur, cihaza otomatik yukle
    Matrix a{{1.0f, -2.0f}, {3.0f, 4.0f}};

    // 2) Fabrika metotlari GPU uzerinde uretir (host trafigi yok)
    Matrix b = Matrix::identity(2);

    // 3) cuBLAS GEMM + ReLU + skaler cikarma, hepsi GPU'da
    Matrix c = (a * b).relu().add_scalar(-0.5f);

    // 4) Fail-fast kurali: download() olmadan host okumasi yapilamaz
    c.download();

    std::cout << "shape: " << c.rows() << "x" << c.cols() << "\n";
    std::cout << "sum  : " << c.sum() << "\n";
    std::cout << "c(0,0): " << c.at(0, 0) << "\n";
    return 0;
}

#include "matrix_pro/matrix_pro.hpp"
#include <iostream>

int main() {
    using matrix_pro::Matrix;

    Matrix a {{
        {1.0f, 2.0f},
        {3.0f, 4.0f}
    }};
    // Kurucu upload() yapti: host_current() == true

    Matrix b = a * a;        // GPU yazdi -> b.mark_host_stale()
    std::cout << "b current? " << b.host_current() << "\n";  // 0

    // Yanlis sira: istisna atar
    try {
        (void)b.at(0, 0);
    } catch (const matrix_pro::MatrixProError& e) {
        std::cout << "beklenen hata: " << e.what() << "\n";
    }

    b.download();            // aynayi tazele
    std::cout << "b(0,0) = " << b.at(0, 0) << "\n";   // 7
    return 0;
}

#include "matrix_pro/matrix_pro.hpp"
#include <iostream>

int main() {
    using matrix_pro::Matrix;
    using matrix_pro::MemoryMode;

    // Cihaza ozel: host aynasi YOK
    Matrix act(4096, 4096, MemoryMode::device_only);
    std::cout << "host_materialized: "
              << act.host_materialized() << "\n";   // 0

    // GPU'da uret ve isle - host'a hic dokunma
    Matrix w = Matrix::glorot(4096, 4096);
    Matrix y = (w * w.transpose()).relu();
    std::cout << "y sum: " << y.sum() << "\n";  // tek host okumasi

    return 0;
}

#include "matrix_pro/matrix_pro.hpp"
#include <iostream>

int main() {
    using namespace matrix_pro;

    try {
        Matrix a{{1.0f, 2.0f}, {3.0f, 4.0f}};
        Matrix b(3, 2);                 // sekil uyusmuyor
        Matrix c = a * b;               // ShapeMismatchError
        (void)c;

    } catch (const ShapeMismatchError& e) {
        std::cerr << "Sekil hatasi: " << e.what() << "\n";

    } catch (const OutOfRangeError& e) {
        std::cerr << "Indeks hatasi: " << e.what() << "\n";

    } catch (const MatrixProError& e) {
        // Tum kutuphane hatalari icin son savunma hatti
        std::cerr << "MatrixFlash-Pro hatasi: " << e.what() << "\n";
        return 1;

    } catch (const std::exception& e) {
        std::cerr << "Beklenmeyen: " << e.what() << "\n";
        return 2;
    }

    return 0;
}
